<script>
    const palettePreview=document.getElementById('invitation-palette-preview');
    function updatePalettePreview(){palettePreview.style.setProperty('--preview-accent',document.getElementById('primary_color').value);palettePreview.style.setProperty('--preview-background',document.getElementById('background_color').value);palettePreview.style.setProperty('--preview-text',document.getElementById('text_color').value);}
    ['primary_color','background_color','text_color'].forEach(function(id){document.getElementById(id).addEventListener('input',updatePalettePreview);});updatePalettePreview();
    const pledgeToggle=document.getElementById('pledge-enabled'),pledgeSettings=document.getElementById('pledge-settings'),pledgePersonalization=document.getElementById('pledge-personalization'),personalizationContext=document.getElementById('personalization-context');
    function syncPledgeSettings(){const enabled=pledgeToggle.checked;pledgeSettings.hidden=!enabled;pledgeSettings.querySelectorAll('input,textarea,select').forEach(function(field){field.disabled=!enabled;});pledgePersonalization.hidden=!enabled;personalizationContext.textContent=enabled?'Includes event, attendance and pledge payment fields.':'Showing event and attendance fields. Enable Pledges to add payment fields.';}
    pledgeToggle.addEventListener('change',syncPledgeSettings);syncPledgeSettings();
    const invitationImage=document.getElementById('invitation_card'),imageStatus=document.getElementById('invitation-image-status'),designForm=document.querySelector('.design-studio');let imageProcessing=false;
    invitationImage.addEventListener('change',async function(){const file=invitationImage.files[0];if(!file)return;imageStatus.textContent='Checking image…';if(file.size<=1900000){imageStatus.textContent='Ready to upload · '+(file.size/1048576).toFixed(1)+' MB';return;}imageProcessing=true;designForm.querySelector('button[type="submit"]').disabled=true;try{const bitmap=await createImageBitmap(file),scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const context=canvas.getContext('2d');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);let quality=.88,blob;do{blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));quality-=.08;}while(blob&&blob.size>1900000&&quality>=.44);if(!blob||blob.size>2048000)throw new Error('Image remains too large');const transfer=new DataTransfer(),name=file.name.replace(/\.[^.]+$/,'.jpg');transfer.items.add(new File([blob],name,{type:'image/jpeg',lastModified:Date.now()}));invitationImage.files=transfer.files;imageStatus.textContent='Optimized and ready · '+(blob.size/1048576).toFixed(1)+' MB';}catch(error){invitationImage.value='';imageStatus.textContent='This image could not be optimized. Please choose a smaller PNG or JPG.';}finally{imageProcessing=false;designForm.querySelector('button[type="submit"]').disabled=false;}});
    designForm.addEventListener('submit',function(event){if(imageProcessing){event.preventDefault();imageStatus.textContent='Please wait while the invitation image is optimized.';}});
</script>
